if(!app.requestSingleInstanceLock())app.quit();else{app.on('second-instance',(_,argv)=>{if(argv.includes('--desktop')||argv.includes('--bigscreen')){win?.setFullScreen(argv.includes('--bigscreen')&&!argv.includes('--desktop'));notify({library:publicLibrary()});}win?.show();win?.focus()});app.whenReady().then(async()=>{win=new BrowserWindow({width:1600,height:1000,minWidth:1000,minHeight:700,title:'Nova Launcher',backgroundColor:'#0b1013',autoHideMenuBar:true,fullscreen:require('./startup-mode.cjs').mode(preferences,process.argv)==='bigscreen',icon:path.join(__dirname,'assets','NOVA.ico'),webPreferences:{preload:path.join(__dirname,'preload.cjs'),contextIsolation:true,nodeIntegration:false,sandbox:true}});win.webContents.setWindowOpenHandler(()=>({action:'deny'}));win.webContents.on('will-navigate',e=>e.preventDefault());win.webContents.session.setPermissionRequestHandler((_,permission,cb)=>cb(permission==='fullscreen'));initializeVault();cloud.initialize();if(cloud.status().connected)await loadNovaProfile();else loadGuestProfile();if(process.argv.includes('--reset-store-library'))await resetStoreLibrary();hydrateAchievements();await win.loadFile(path.join(__dirname,'index.html'));updater.start();win.webContents.on('console-message',details=>{if(details.level>=2)log('UI: '+details.message)});sync().then(()=>{bootReady=true;notify({library:publicLibrary()});hydraMonitor.start();setInterval(()=>{if(profileReady)sync().then(v=>notify({library:v})).catch(log);},300000);}).catch(e=>{bootReady=true;notify({error:e.message})});});let quitting=false;app.on('before-quit',event=>{steamNetwork.close();steamQR.stop();if(profileReady&&!quitting){event.preventDefault();quitting=true;archiveProfile(cloud.status().id||'guest');Promise.race([cloud.push(cloudSnapshot()).catch(()=>{}),new Promise(resolve=>setTimeout(resolve,4000))]).finally(()=>app.quit());return;}if(discordProcess)discordProcess.kill()});app.on('window-all-closed',()=>app.quit());}

let newsTask;async function refreshNews(){if(newsTask)return newsTask;newsTask=(async()=>{const games=library.games.filter(g=>/^\d+$/.test(g.steamId||''));let next=0;const folder=path.join(L.data,'News');fs.mkdirSync(folder,{recursive:true});await Promise.all(Array.from({length:3},async()=>{while(next<games.length){const g=games[next++],f=path.join(folder,g.steamId+'.json');if(fs.existsSync(f)&&Date.now()-fs.statSync(f).mtimeMs<21600000)continue;try{const v=await request('https://api.steampowered.com/ISteamNews/GetNewsForApp/v2/?appid='+g.steamId+'&count=50&maxlength=0&feeds=steam_community_announcements');v.novaFull=true;fs.writeFileSync(f,JSON.stringify(v));}catch{}}}));notify({library:publicLibrary()});})().finally(()=>newsTask=null);return newsTask;}

let lastRunningAt=Date.now(),runningIds=new Set(),lastActivitySave=0;const runningSources=new Map();async function running(){const list=await I.processes(),now=Date.now(),ids=library.games.filter(g=>I.matches(g,list).length).map(g=>g.id);for(const id of ids){const g=game(id);if(runningIds.has(id)){const seconds=Math.min(10,Math.max(0,(now-lastRunningAt)/1000));g.playtime=(g.playtime||0)+seconds;const matching=g.copies.filter(c=>I.matches({...g,copies:[c]},list).length),preferred=matching.find(c=>c.id===runningSources.get(id)),copy=preferred||(matching.length===1?matching[0]:null);if(copy){copy.playtime=(copy.playtime||0)+seconds;copy.playtimeOrigin=copy.playtimeOrigin||'Nova';copy.lastPlayed=new Date().toISOString();}}else g.lastPlayed=new Date().toISOString();}if((ids.length||runningIds.size)&&now-lastActivitySave>60000){fs.writeFileSync(path.join(L.data,'library.json'),JSON.stringify(library));lastActivitySave=now;}for(const id of runningIds)if(!ids.includes(id))runningSources.delete(id);lastRunningAt=now;runningIds=new Set(ids);return ids;}

const hydraProgress=require('./hydra-progress.cjs');
function cachedHydraProfile(g){if(!g.hydraKey||!hydraAccount.status().connected)return null;const owner=crypto.createHash('sha256').update(String(vault.hydra.user?.id||'')).digest('hex');const a=L.read(path.join(L.data,'achievements',g.hydraKey.replace(':','-')+'.json'));if(a.owner!==owner||!Array.isArray(a.items)||!a.items.length)return null;return hydraProgress.reconcile(a,null,hydraLocalProgress(g));}
function hydraLocalProgress(g){return g.hydraKey?.startsWith('steam:')&&g.copies?.some(c=>c.source==='Hydra'&&c.installed)?hydraProgress.localProgress(g.hydraKey.split(':')[1]):undefined;}
function cacheProfiles(g){const profiles={...g.cloudAchievementProfiles};for(const [source,profile]of Object.entries(profiles)){if(source==='Hydra'&&hydraAccount.status().connected&&profile.owner!==crypto.createHash('sha256').update(String(vault.hydra.user?.id||'')).digest('hex'))delete profiles[source];if(source==='Steam'&&preferences.steamUserId&&profile.owner!==preferences.steamUserId)delete profiles[source];}const hydra=cachedHydraProfile(g);if(hydra)profiles.Hydra=hydra;
 if(g.steamId){const a=L.read(path.join(L.data,'steam-ach-'+g.steamId+'.json'));if(a.owner===preferences.steamUserId&&Array.isArray(a.game?.achievements)&&a.game.achievements.every(a=>a.id))profiles.Steam={items:a.game.achievements,updated:a.updated,owner:a.owner,error:''};}
 const gogProfile=preferences.gogLinked?gog.profile(g):null;if(gogProfile)profiles.GOG=gogProfile;const epicProfile=platformAccounts.cachedEpicProfile(g);if(epicProfile)profiles.Epic=epicProfile;return profiles;}
function applyProfiles(g,profiles){if(!Object.keys(profiles).length){if(g.achievementProfiles){g.achievementProfiles={};g.achievements=[];g.achievementTotal=0;g.achievementUnlocked=0;g.achievementSource='';}return;}g.achievementProfiles=profiles;g.achievementView='all';Object.assign(g,achievementModel.summarize(profiles));}
function hydrateAchievements(){for(const g of library.games){gameInfo.cached(g);applyProfiles(g,cacheProfiles(g));}}
const achievementRequests=new Map();async function refreshAchievements(g){if(achievementRequests.has(g.id))return achievementRequests.get(g.id);const task=(async()=>{const profiles=cacheProfiles(g),errors=[];await Promise.all([
(async()=>{if(!g.copies?.some(c=>c.source==='Epic')||!platformAccounts.status().epic.connected)return;try{const profile=await platformAccounts.achievements(g);if(profile)profiles.Epic=profile;else errors.push('Epic: obiettivi non esposti per questo gioco.');}catch(e){if(profiles.Epic)profiles.Epic.error=e.message;else errors.push(e.message);}})(),
 (async()=>{if(!g.steamId||(!vault.steamKey&&!steamQR.accessToken()))return;const row={...g};try{if(await steam.achievements(row))profiles.Steam={items:row.achievements,updated:new Date().toISOString(),owner:preferences.steamUserId,error:''};}catch(e){if(profiles.Steam)profiles.Steam.error=e.message;else errors.push('Steam: '+e.message);}})(),
 (async()=>{if(!g.hydraKey)return;try{if(hydraAccount.status().connected){const direct=await hydraAccount.achievements(g);if(direct){profiles.Hydra=hydraProgress.reconcile(direct,profiles.Hydra,hydraLocalProgress(g));const file=path.join(L.data,'achievements',g.hydraKey.replace(':','-')+'.json');fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file+'.tmp',JSON.stringify(profiles.Hydra));fs.renameSync(file+'.tmp',file);return;}}if(!g.copies.some(c=>c.source==='Hydra'&&c.installed))return;await I.run(path.join(L.root,'tools','node.exe'),[path.join(L.root,'tools','achievements.cjs'),L.data,g.hydraKey],{timeout:60000});const fresh=cacheProfiles(g).Hydra;if(fresh)profiles.Hydra=fresh;}catch(e){if(profiles.Hydra)profiles.Hydra.error='Aggiornamento non disponibile: mostro gli ultimi progressi confermati.';else errors.push('Hydra: obiettivi personali non disponibili.');log(e);}})()
 ]);applyProfiles(g,profiles);if(errors.length)g.achievementError=[g.achievementError,...errors].filter(Boolean).join(' · ');fs.writeFileSync(path.join(L.data,'library.json'),JSON.stringify(library));queueCloud();return g;})();achievementRequests.set(g.id,task);try{return await task}finally{achievementRequests.delete(g.id)}}

const refreshProfileAchievements=require('./profile-refresh.cjs')({owner:()=>[cloud.status().id||'guest',preferences.steamUserId||'',vault.hydra?.user?.id||'',...['Steam','Hydra','Epic','GOG'].map(storeConnected)].join(':'),games:()=>eligibleLibrary().games,refresh:async visible=>{const current=library.games.find(g=>g.id===visible.id);if(current)await refreshAchievements(current);},notify:()=>notify({profileAchievements:true})});
let webSyncBusy=false;setInterval(async()=>{if(!profileReady||!cloud.status().connected||webSyncBusy)return;webSyncBusy=true;try{await cloud.refresh(cloudSnapshot);if(!globalThis.lastPresence||Date.now()-globalThis.lastPresence>30000){const uid=cloud.status().id;const social=await friends();if(uid===cloud.status().id&&social.status==='ready'){await cloud.presence(require('./presence.cjs').snapshot(social,preferences.friendGroups));globalThis.lastPresence=Date.now();}}await cloud.remoteSync(async()=>{if(syncing)return false;await sync();await cloud.push(cloudSnapshot());notify({library:publicLibrary()});return library.connectionErrors?.length?'Library synced. Some stores could not be refreshed; check connections on your PC.':'Library synced from Nova on your PC.';});}catch(e){log('Web sync unavailable: '+e.message);}finally{webSyncBusy=false;}},15000)?.unref?.();
